<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateChannelVO;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Holder\TemplateChannelAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TemplateChannelAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TemplateChannelAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getChannel returns null on a freshly created holder.
         */
        public function testChannelNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithTemplateChannelAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isChannelAssigned());
            $this->assertNull($holder->getChannel());
        }
}
class ImplWithTemplateChannelAttributeHolderUnitTest
{
  use TemplateChannelAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedChannelRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultChannel();
    }}
